INSERT INTO mapping.phase3_capabilities
(capability_id,standard_id,domain,entity,field_or_element,semantic_meaning,evidence_type,limitations,review_status)
VALUES
('CAP-GTFS-SCHEDULE-TRIP-STOP-TIMES','M03-GTFS-SCHEDULE-2026-04','scheduled public transport','trip, stop, route','routes.txt; trips.txt; stops.txt; stop_times.txt','GTFS Schedule Reference defines routes, trips, stops, and arrival/departure times associated with trips.','FIELD','Does not establish legal coverage of Annex point 1, historical/observed data, all modes, NAP access, or compliance.','NEEDS_REVIEW'),
('CAP-GTFS-FEED-PUBLISHER-METADATA','M03-GTFS-SCHEDULE-2026-04','dataset metadata','feed','feed_info.txt: feed_publisher_name, feed_publisher_url, feed_version','GTFS Schedule can express dataset publisher identity and URL and feed version metadata.','FIELD','Publisher is not necessarily the source of each underlying data item; does not prove an Article 8(3) request or response.','NEEDS_REVIEW'),
('CAP-GTFS-DATASET-ATTRIBUTION','M03-GTFS-SCHEDULE-2026-04','dataset attribution','dataset, agency, route, trip','attributions.txt','GTFS Schedule provides attribution records applicable at dataset, agency, route, or trip scope.','FIELD','Attribution is not necessarily the legally relevant source for each reused datum and does not prove disclosure to a user.','NEEDS_REVIEW'),
('CAP-NETEX-PT-NETWORK-TIMETABLE-EXCHANGE','M03-NETEX-EPIP-2017','public transport static data','network and timetable','CEN/TS 16614 parts 1–4; EPIP profile identity','Public CEN ecosystem material identifies NeTEx exchange for public transport network and scheduled timetable concepts, with EPIP as a named European profile.','EXTERNAL_DOCUMENT','Full normative profile detail unavailable in reviewed public sources; national minimum profile applicable under Regulation 2017/1926 Article 4(2) remains unknown.','NEEDS_REVIEW')
