INSERT INTO mapping.phase3_exceptions
(exception_id,requirement_id,exception_type,reason,justification,evidence_expectations,review_status)
VALUES
('M03-EXC-A05-DEADLINE','EU-2017-1926-REQ-A05-P03-001','DEADLINE','Legal deadline and geographic applicability are not transport-format fields.','The frozen requirement is the 2025-12-01 deadline for Annex point 2.1 data on the comprehensive TEN-T network. Calendar/feed date fields cannot establish timely legal provision.','Applicable data/geography determination; dated NAP publication/access records; evidence supporting availability by the legal deadline.','NEEDS_REVIEW'),
('M03-EXC-A08-SOURCE-REQUEST','EU-2017-1926-REQ-A08-P03-001-01','EXTERNAL_EVIDENCE','The duty is conditional on reuse and a data holder request; technical publisher/attribution metadata alone does not prove the source disclosure or response.','GTFS fields support only bounded dataset publisher/attribution capabilities; request handling and source provenance require external documentary evidence.','Reuse context; request record; provenance of the reused data; response/disclosure record linked to the request.','NEEDS_REVIEW'),
('M03-EXC-A09-RANDOM-CHECKS','EU-2017-1926-REQ-A09-P03-RANDOM_CHECKS','MANUAL_ASSESSMENT','Random accuracy checks are an institutional supervisory act, not a capability of a transport exchange format.','The frozen duty assigns checks to Member States and concerns accuracy of Article 9(2)(c) declarations; this pilot supplies no method, frequency, or sample size.','Authority/process records; sampled declarations and corroborating evidence; documented check outcome and method where established.','NEEDS_REVIEW')
